def SHIP(n): return f'<p>We make every order to your design and ship it to your door in the {n} area. Delivery usually takes 15 to 20 days after design approval and deposit. Orders ship from outside the United States, so duties or taxes, if any, are paid by the customer. See <a href="/guides/how-long-do-custom-uniforms-take">how long an order takes</a>.</p>'
CITY=[]
for cs,(n,st,areas,hub,cl,loc) in CITIES.items():
    back=f'Back to the <a href="/{cs}">{n} hub</a>.'
    CITY.append(dict(slug=cs,root=True,
     title=f'Custom Work Uniforms for {n} Trade Crews',
     desc=f'Custom full-print work shirts, hoodies and vests for {n} HVAC, plumbing, roofing, landscaping and pressure washing crews. Free design in 24 hours.',
     h1=f'Custom work uniforms for <em>{n}</em> crews',
     intro=f'Matching uniforms with your logo and phone number for {n} trade businesses. Free design in 24 hours, no setup fees, shipped to your door.',
     sections=[('Pick your trade','<ul>'+''.join(f'<li><a href="/{cs}/{t[1]}">{t[3]} in {n}</a></li>' for t in TR)+'</ul>'),
      (f'Why {n} crews dress for the weather',f'<p>{hub}</p>'),
      ('Where we deliver',f'<p>Crews across the {n} area: {areas}, and the suburbs around them. A back print with your company name, phone number and the areas you serve turns every truck and job site into local advertising.</p>'),
      ('How it works',SHIP(n)+'<p><a href="#design">Send your logo</a> and crew size for a free design within 24 hours, with no obligation.</p>')],
     faqs=[(f'Where can I get custom work uniforms in {n}?',f'CrewWear Custom makes custom full-print work shirts, hoodies and vests with your logo and phone number, and ships them to businesses across {n}. The design is free within 24 hours.'),
      (f'Do you have a store in {n}?','No. We make orders to your design and ship them to you, which suits crews that cannot take time to visit a shop.'),
      (f'What do {n} trade crews wear?',f'In {cl}, crews commonly choose lightweight, moisture-wicking long sleeves and a cap, with a hoodie for cooler mornings.'),
      (f'How long does an order take in {n}?','Usually 15 to 20 days after design approval and deposit. Order a few weeks before you need the crew in uniform.')]))
    for i,(tk,ts,tt,th,tl,tlab) in enumerate(TR):
        intro,prn,prod=GEN[tk]
        CITY.append(dict(slug=f'{cs}/{ts}',root=True,
         title=f'{tt} in {n}',
         desc=f'Custom {th.lower()} with your logo for {n} crews. Free design in 24 hours, no setup fees, shipped to your door.',
         h1=f'{th} in <em>{n}</em>',intro=intro,
         sections=[(f'Working in {n}',f'<p>{loc[i]}</p>'),('What to wear',f'<p>{prod}</p>'),('What to print',prn),(f'Delivery to {n}',SHIP(n)),
          (f'More on {tk.replace("-"," ")} uniforms',f'<p>Read about <a href="{tl}">{tlab}</a> and <a href="/guides/how-long-do-custom-uniforms-take">how long an order takes</a>. {back}</p>')],
         faqs=[(f'Where can I get {th.lower()} in {n}?',f'CrewWear Custom makes {th.lower()} with your logo and phone number and ships them to {n}. Send your logo for a free design in 24 hours.'),
          (f'What should {tk.replace("-"," ")} crews wear in {n}?',f'With {cl}, lightweight, moisture-wicking pieces that dry quickly are the practical choice, plus a cap and a hoodie for cooler starts.'),
          ('Can I match the uniforms to my truck colours?','Yes. We build the design around your logo and brand colours so crew and trucks look like one brand.'),
          ('Can I order for a small crew?','Yes. Tell us your crew size in the form and we will confirm the minimum for the pieces you want.')]))
